// Admin entry point.
// Feature files are isolated by responsibility while classic-script compatibility preserves
// the existing global inline handlers generated by the current admin UI templates.
const scripts = [
  "./runtime.js",
  "./common.js",
  "./dashboard.js",
  "./product.js",
  "./variant.js",
  "./category.js",
  "./brand.js",
  "./order.js",
  "./voucher.js",
  "./events.js",
  "./user.js",
  "./review.js",
  "./report.js",
];

function loadClassic(src) {
  return new Promise((resolve, reject) => {
    const script = document.createElement("script");
    script.src = new URL(src, import.meta.url).href;
    script.async = false;
    script.onload = resolve;
    script.onerror = () => reject(new Error(`Không thể tải Admin module: ${src}`));
    document.head.appendChild(script);
  });
}

try {
  for (const src of scripts) await loadClassic(src);
  if (typeof window.init === "function") {
    await window.init();
  } else if (typeof init === "function") {
    await init();
  } else {
    throw new Error("Admin init() không tồn tại sau khi tải module");
  }
} catch (error) {
  console.error("ADMIN MODULE BOOTSTRAP ERROR:", error);
  const app = document.getElementById("app");
  if (app) app.innerHTML = `<div style="padding:24px;color:#991b1b;font-family:Arial,sans-serif">Không thể khởi tạo trang quản trị. Vui lòng mở Console để xem chi tiết.</div>`;
}
